import * as k8s from '@pulumi/kubernetes';

const appLabels = { app: '{{app_name}}' };
new k8s.apps.v1.Deployment('{{app_name}}', {
  spec: {
    selector: { matchLabels: appLabels },
    replicas: 3,
    template: {
      metadata: { labels: appLabels },
      spec: { containers: [{ name: '{{app_name}}', image: '{{image}}' }] },
    },
  },
});
